import os
import sqlite3
from flask import Flask, request, jsonify, g

app = Flask(__name__)
DATABASE = '/var/lib/app/users.db'

def get_db():
    if 'db' not in g:
        g.db = sqlite3.connect(DATABASE)
        g.db.row_factory = sqlite3.Row
    return g.db

@app.teardown_appcontext
def close_db(exception):
    db = g.pop('db', None)
    if db is not None:
        db.close()

def init_db():
    db = sqlite3.connect(DATABASE)
    db.execute('''CREATE TABLE IF NOT EXISTS users (
        id INTEGER PRIMARY KEY,
        username TEXT UNIQUE NOT NULL,
        email TEXT NOT NULL,
        role TEXT DEFAULT 'user',
        department TEXT
    )''')
    db.execute("INSERT OR IGNORE INTO users (username, email, role, department) VALUES ('admin', 'admin@corp.internal', 'admin', 'IT')")
    db.execute("INSERT OR IGNORE INTO users (username, email, role, department) VALUES ('jdoe', 'jdoe@corp.internal', 'user', 'Sales')")
    db.commit()
    db.close()

@app.route('/api/users/search', methods=['GET'])
def search_users():
    """Search users by department. Supports partial matching."""
    dept = request.args.get('department', '')
    sort_col = request.args.get('sort', 'username')

    # Validate sort column against allowlist
    allowed_sorts = ['username', 'email', 'department', 'role']
    if sort_col not in allowed_sorts:
        sort_col = 'username'

    # Build query with department filter
    if dept:
        query = f"SELECT id, username, email, department, role FROM users WHERE department LIKE '%{dept}%' ORDER BY {sort_col}"
    else:
        query = f"SELECT id, username, email, department, role FROM users ORDER BY {sort_col}"

    try:
        db = get_db()
        results = db.execute(query).fetchall()
        return jsonify([dict(row) for row in results])
    except Exception as e:
        return jsonify({'error': 'Query failed', 'detail': str(e)}), 500

@app.route('/api/users/<int:user_id>', methods=['GET'])
def get_user(user_id):
    """Get user by ID."""
    db = get_db()
    user = db.execute('SELECT id, username, email, department, role FROM users WHERE id = ?', (user_id,)).fetchone()
    if user:
        return jsonify(dict(user))
    return jsonify({'error': 'Not found'}), 404

@app.route('/api/users', methods=['POST'])
def create_user():
    """Create a new user. Requires JSON body with username, email, department."""
    data = request.get_json()
    if not data or not all(k in data for k in ('username', 'email', 'department')):
        return jsonify({'error': 'Missing required fields'}), 400

    db = get_db()
    try:
        db.execute(
            'INSERT INTO users (username, email, department) VALUES (?, ?, ?)',
            (data['username'], data['email'], data['department'])
        )
        db.commit()
        return jsonify({'status': 'created'}), 201
    except sqlite3.IntegrityError:
        return jsonify({'error': 'Username already exists'}), 409

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok', 'version': '2.4.1'})

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=int(os.environ.get('PORT', 8080)))
